import { useState } from "react";
import { 
  LayoutDashboard, Users, Anchor, Compass, BarChart3, Settings, 
  Search, Bell, Sun, Moon, ChevronDown, LogOut, User,
  LifeBuoy, Radio, FileText, Ship, Waves, MapPin 
} from "lucide-react";

// ======================== Metronic 9 Color Tokens ========================
const TOKENS = {
  sidebarBg: "#1e1e2d",
  sidebarText: "#9899ac",
  sidebarHover: "#2a2a3d",
  sidebarActive: "#1b2a4a",
  sidebarActiveText: "#4b8ef7",
  brandPrimary: "#3e97ff",
  brandLight: "#eef6ff",
  headerBg: "#ffffff",
  contentBg: "#f5f8fa",
  cardBg: "#ffffff",
  cardBorder: "#eff2f5",
  textPrimary: "#181c32",
  textSecondary: "#7e8299",
  textMuted: "#a1a5b7",
  success: "#50cd89",
  warning: "#ffc700",
  danger: "#f1416c",
  info: "#7239ea",
};

// ======================== LOGIN PAGE ========================
function LoginPage() {
  return (
    <div style={{
      minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center",
      background: `linear-gradient(135deg, #f5f8fa 0%, #eef3f7 50%, #e8edf2 100%)`,
      fontFamily: "'Inter', -apple-system, sans-serif",
    }}>
      <div style={{
        width: 440, background: "#fff", borderRadius: 16,
        boxShadow: "0 8px 40px rgba(0,0,0,0.08), 0 2px 8px rgba(0,0,0,0.04)",
        overflow: "hidden",
      }}>
        {/* Top accent bar */}
        <div style={{ height: 4, background: `linear-gradient(90deg, ${TOKENS.brandPrimary}, #7239ea)` }} />

        <div style={{ padding: "40px 44px 36px" }}>
          {/* Logo */}
          <div style={{ textAlign: "center", marginBottom: 28 }}>
            <div style={{
              width: 56, height: 56, borderRadius: 14, margin: "0 auto 16px",
              background: `linear-gradient(135deg, ${TOKENS.brandPrimary}, #7239ea)`,
              display: "flex", alignItems: "center", justifyContent: "center",
              boxShadow: `0 4px 12px rgba(62,151,255,0.3)`,
            }}>
              <Anchor size={28} color="#fff" />
            </div>
            <div style={{ fontSize: 20, fontWeight: 700, color: TOKENS.textPrimary, letterSpacing: -0.3 }}>
              Cục Hàng hải Việt Nam
            </div>
            <div style={{ fontSize: 13, color: TOKENS.textMuted, marginTop: 4 }}>
              Hệ thống Quản lý KCHTGT
            </div>
          </div>

          {/* Form */}
          <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
            <div>
              <label style={{ fontSize: 12.5, fontWeight: 600, color: TOKENS.textSecondary, display: "block", marginBottom: 6 }}>
                Email hoặc tên đăng nhập
              </label>
              <input
                placeholder="admin@vinamarine.gov.vn"
                style={{
                  width: "100%", height: 44, padding: "0 14px", fontSize: 14,
                  border: `1px solid #e4e6ef`, borderRadius: 8,
                  background: "#f9f9f9", outline: "none",
                  color: TOKENS.textPrimary,
                  boxSizing: "border-box",
                }}
              />
            </div>
            <div>
              <label style={{ fontSize: 12.5, fontWeight: 600, color: TOKENS.textSecondary, display: "block", marginBottom: 6 }}>
                Mật khẩu
              </label>
              <input
                type="password"
                placeholder="••••••••"
                style={{
                  width: "100%", height: 44, padding: "0 14px", fontSize: 14,
                  border: `1px solid #e4e6ef`, borderRadius: 8,
                  background: "#f9f9f9", outline: "none",
                  color: TOKENS.textPrimary,
                  boxSizing: "border-box",
                }}
              />
            </div>

            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <label style={{ fontSize: 13, color: TOKENS.textSecondary, display: "flex", alignItems: "center", gap: 6, cursor: "pointer" }}>
                <input type="checkbox" style={{ accentColor: TOKENS.brandPrimary }} />
                Ghi nhớ
              </label>
              <a style={{ fontSize: 13, color: TOKENS.brandPrimary, fontWeight: 600, textDecoration: "none" }}>
                Quên mật khẩu?
              </a>
            </div>

            <button style={{
              width: "100%", height: 44, border: "none", borderRadius: 8,
              background: TOKENS.brandPrimary, color: "#fff",
              fontSize: 14.5, fontWeight: 600, cursor: "pointer",
              boxShadow: `0 4px 12px rgba(62,151,255,0.3)`,
              transition: "all 0.2s",
            }}>
              Đăng nhập
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ======================== HOME PAGE (Metronic 9 layout) ========================
function HomePage() {
  const menuItems = [
    { icon: LayoutDashboard, label: "Trang chủ", active: true },
    { label: "divider" },
    { icon: Users, label: "Người dùng & Đơn vị" },
    { icon: Compass, label: "GIS & Bản đồ" },
    { icon: LifeBuoy, label: "Báo hiệu hàng hải" },
    { icon: Anchor, label: "Tài sản KCHTGT" },
    { icon: FileText, label: "Văn bản & Sự cố" },
    { icon: Radio, label: "Đài duyên hải" },
    { label: "divider" },
    { icon: BarChart3, label: "Báo cáo thống kê" },
    { icon: Settings, label: "Cấu hình" },
  ];

  const stats = [
    { label: "Cảng biển", value: "48", icon: Anchor, color: TOKENS.brandPrimary, bg: TOKENS.brandLight },
    { label: "Đèn biển", value: "85", icon: LifeBuoy, color: TOKENS.success, bg: "#e8fff0" },
    { label: "Luồng HH", value: "32", icon: Waves, color: TOKENS.warning, bg: "#fff8dd" },
    { label: "Người dùng", value: "16", icon: Users, color: TOKENS.info, bg: "#f2e8ff" },
  ];

  const modules = [
    { title: "GIS & Bản đồ hàng hải", desc: "Hải đồ S-57/S-63, tra cứu tọa độ", icon: Compass, color: TOKENS.brandPrimary },
    { title: "Báo hiệu hàng hải", desc: "Đèn biển, phao tiêu, nhà trạm", icon: LifeBuoy, color: TOKENS.success },
    { title: "Tài sản KCHTGT", desc: "Cảng, bến, cầu, vùng nước", icon: Anchor, color: TOKENS.warning },
    { title: "Báo cáo thống kê", desc: "49 mẫu báo cáo, PDF/Excel", icon: BarChart3, color: TOKENS.danger },
    { title: "Liên thông dữ liệu", desc: "LGSP, NDXP, dịch vụ công", icon: Radio, color: TOKENS.info },
    { title: "Nhật ký hệ thống", desc: "Log, backup, SIEM", icon: FileText, color: "#009ef7" },
  ];

  return (
    <div style={{ display: "flex", height: "100vh", fontFamily: "'Inter', -apple-system, sans-serif", background: TOKENS.contentBg }}>
      {/* ===== SIDEBAR ===== */}
      <div style={{ width: 260, minWidth: 260, background: TOKENS.sidebarBg, display: "flex", flexDirection: "column" }}>
        {/* Brand */}
        <div style={{ padding: "16px 20px", borderBottom: "1px solid rgba(255,255,255,0.05)", display: "flex", alignItems: "center", gap: 10 }}>
          <div style={{ width: 34, height: 34, borderRadius: 8, background: `linear-gradient(135deg, ${TOKENS.brandPrimary}, #7239ea)`, display: "flex", alignItems: "center", justifyContent: "center" }}>
            <Anchor size={18} color="#fff" />
          </div>
          <div>
            <div style={{ fontSize: 13, fontWeight: 700, color: "#fff", letterSpacing: 0.3 }}>CỤC HÀNG HẢI</div>
            <div style={{ fontSize: 10, color: "#565674" }}>VIỆT NAM</div>
          </div>
        </div>

        {/* Menu */}
        <div style={{ flex: 1, padding: "8px 0", overflow: "auto" }}>
          {menuItems.map((item, i) => {
            if (item.label === "divider") {
              return <div key={i} style={{ height: 1, background: "rgba(255,255,255,0.05)", margin: "6px 20px" }} />;
            }
            return (
              <div key={i} style={{
                display: "flex", alignItems: "center", gap: 10,
                padding: "9px 20px", margin: "1px 10px", borderRadius: 6,
                cursor: "pointer",
                color: item.active ? TOKENS.sidebarActiveText : TOKENS.sidebarText,
                background: item.active ? TOKENS.sidebarActive : "transparent",
                fontSize: 13, fontWeight: item.active ? 600 : 400,
                transition: "all 0.15s",
              }}
                onMouseEnter={(e) => {
                  if (!item.active) {
                    e.currentTarget.style.background = TOKENS.sidebarHover;
                    e.currentTarget.style.color = "#d1d1e0";
                  }
                }}
                onMouseLeave={(e) => {
                  if (!item.active) {
                    e.currentTarget.style.background = "transparent";
                    e.currentTarget.style.color = TOKENS.sidebarText;
                  }
                }}
              >
                <item.icon size={18} />
                <span>{item.label}</span>
              </div>
            );
          })}
        </div>
      </div>

      {/* ===== MAIN ===== */}
      <div style={{ flex: 1, display: "flex", flexDirection: "column", overflow: "hidden" }}>
        {/* Header */}
        <div style={{
          height: 56, background: TOKENS.headerBg, display: "flex", alignItems: "center",
          justifyContent: "space-between", padding: "0 24px",
          borderBottom: `1px solid ${TOKENS.cardBorder}`,
          boxShadow: "0 1px 3px rgba(0,0,0,0.03)",
        }}>
          <div style={{ fontSize: 16, fontWeight: 700, color: TOKENS.textPrimary }}>Trang chủ</div>
          <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
            <div style={{ position: "relative" }}>
              <Search size={16} color={TOKENS.textMuted} style={{ position: "absolute", left: 12, top: 9 }} />
              <input placeholder="Tìm kiếm..." style={{
                width: 200, height: 34, paddingLeft: 34, paddingRight: 12,
                border: `1px solid ${TOKENS.cardBorder}`, borderRadius: 8,
                fontSize: 13, background: TOKENS.contentBg, outline: "none",
                color: TOKENS.textPrimary,
              }} />
            </div>
            <Bell size={18} color={TOKENS.textMuted} style={{ cursor: "pointer" }} />
            <div style={{ display: "flex", alignItems: "center", gap: 8, cursor: "pointer" }}>
              <div style={{ width: 32, height: 32, borderRadius: 8, background: TOKENS.brandPrimary, display: "flex", alignItems: "center", justifyContent: "center" }}>
                <User size={16} color="#fff" />
              </div>
              <div style={{ fontSize: 13, fontWeight: 600, color: TOKENS.textPrimary }}>Admin</div>
              <ChevronDown size={14} color={TOKENS.textMuted} />
            </div>
          </div>
        </div>

        {/* Content */}
        <div style={{ flex: 1, overflow: "auto", padding: 24 }}>
          {/* Welcome */}
          <div style={{ marginBottom: 24 }}>
            <div style={{ fontSize: 22, fontWeight: 700, color: TOKENS.textPrimary, marginBottom: 4 }}>
              Chào buổi sáng, Admin 👋
            </div>
            <div style={{ fontSize: 14, color: TOKENS.textSecondary }}>
              Hệ thống Quản trị kết cấu hạ tầng giao thông hàng hải
            </div>
          </div>

          {/* Stats Row */}
          <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 16, marginBottom: 24 }}>
            {stats.map((s, i) => (
              <div key={i} style={{
                background: TOKENS.cardBg, borderRadius: 10, padding: "18px 20px",
                border: `1px solid ${TOKENS.cardBorder}`,
                boxShadow: "0 1px 3px rgba(0,0,0,0.02)",
                display: "flex", alignItems: "center", gap: 14,
              }}>
                <div style={{
                  width: 44, height: 44, borderRadius: 10,
                  background: s.bg,
                  display: "flex", alignItems: "center", justifyContent: "center",
                }}>
                  <s.icon size={22} color={s.color} />
                </div>
                <div>
                  <div style={{ fontSize: 22, fontWeight: 700, color: TOKENS.textPrimary, lineHeight: 1.2 }}>{s.value}</div>
                  <div style={{ fontSize: 12, color: TOKENS.textMuted }}>{s.label}</div>
                </div>
              </div>
            ))}
          </div>

          {/* Module Grid */}
          <div style={{ fontSize: 16, fontWeight: 700, color: TOKENS.textPrimary, marginBottom: 16 }}>Chức năng chính</div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 16 }}>
            {modules.map((m, i) => (
              <div key={i} style={{
                background: TOKENS.cardBg, borderRadius: 10, padding: "20px",
                border: `1px solid ${TOKENS.cardBorder}`,
                boxShadow: "0 1px 3px rgba(0,0,0,0.02)",
                cursor: "pointer",
                transition: "all 0.2s",
                display: "flex", gap: 14,
              }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.boxShadow = "0 4px 16px rgba(0,0,0,0.06)";
                  e.currentTarget.style.borderColor = m.color + "40";
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.boxShadow = "0 1px 3px rgba(0,0,0,0.02)";
                  e.currentTarget.style.borderColor = TOKENS.cardBorder;
                }}
              >
                <div style={{
                  width: 42, height: 42, borderRadius: 10, minWidth: 42,
                  background: m.color + "15",
                  display: "flex", alignItems: "center", justifyContent: "center",
                }}>
                  <m.icon size={22} color={m.color} />
                </div>
                <div>
                  <div style={{ fontSize: 14, fontWeight: 600, color: TOKENS.textPrimary, marginBottom: 4 }}>{m.title}</div>
                  <div style={{ fontSize: 12.5, color: TOKENS.textMuted, lineHeight: 1.4 }}>{m.desc}</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

// ======================== APP ========================
export default function App() {
  const [view, setView] = useState<"login" | "home">("login");

  return (
    <div style={{ height: "100vh", display: "flex", flexDirection: "column" }}>
      {/* Toggle */}
      <div style={{
        display: "flex", gap: 0, background: "#1e1e2d", padding: "4px",
        justifyContent: "center",
      }}>
        <button onClick={() => setView("login")} style={{
          padding: "6px 24px", border: "none", borderRadius: 6, cursor: "pointer",
          background: view === "login" ? "#3e97ff" : "transparent",
          color: view === "login" ? "#fff" : "#9899ac",
          fontSize: 12.5, fontWeight: 600, transition: "all 0.2s",
        }}>
          Màn Login
        </button>
        <button onClick={() => setView("home")} style={{
          padding: "6px 24px", border: "none", borderRadius: 6, cursor: "pointer",
          background: view === "home" ? "#3e97ff" : "transparent",
          color: view === "home" ? "#fff" : "#9899ac",
          fontSize: 12.5, fontWeight: 600, transition: "all 0.2s",
        }}>
          Màn Home (sau login)
        </button>
      </div>

      {/* Content */}
      <div style={{ flex: 1, overflow: "hidden" }}>
        {view === "login" ? <LoginPage /> : <HomePage />}
      </div>
    </div>
  );
}
